"""Complete 24 original psychopharmacology and psychiatric-emergency questions."""
from create_psych_drug_safety import rows,q,DE,BP,CI,ref
from qbank_authoring import finalize
CT=ref('BAP catatonia guideline, including malignant catatonia and NMS','https://pmc.ncbi.nlm.nih.gov/articles/PMC10101189/')
SH=ref('NICE self-harm assessment and recurrence prevention','https://www.nice.org.uk/guidance/ng225/chapter/Recommendations')
AG=ref('NICE short-term violence/aggression management','https://www.nice.org.uk/guidance/ng10/chapter/recommendations')

q('After a potent antipsychotic dose increase, a patient develops high fever, generalized rigidity, altered mental status, autonomic instability and high CK. Which diagnosis is most likely?', 'Neuroleptic malignant syndrome',[
 ('Acute dystonia alone','It does not account for this severe systemic hyperthermic syndrome.'),('Serotonin toxicity as established without a serotonergic exposure','The dopamine-blocker relationship and rigidity favor NMS, though differential assessment is essential.'),('Uncomplicated medication-induced parkinsonism','This lacks the acute febrile systemic toxicity pattern.')],
 'Recognize a potentially fatal drug-associated syndrome','**Dopamine-blocking exposure with rigidity and systemic instability raises concern for NMS.**',['CK supports muscle injury but is not a unique diagnostic marker.','Infection, heat illness, catatonia and other drug syndromes are important alternatives.'],'**Stop the suspected causative drug and provide urgent medical support.**',['Monitor temperature, kidneys, electrolytes and complications.','Specific adjuncts depend on severity and specialist assessment.'],[['Exposure','Dopamine blockade'],['Motor','Often marked rigidity'],['Systemic','Fever and autonomic instability']],[CT],style='clinical_scenario')

q('After adding a serotonergic drug, a patient rapidly develops agitation, sweating, diarrhea, inducible clonus and hyperreflexia. Which diagnosis is most likely?', 'Serotonin toxicity',[
 ('Antimuscarinic poisoning','Dryness and reduced bowel activity would fit better than sweating and diarrhea.'),('NMS as the best fit despite prominent clonus and serotonergic timing','NMS more often has a different exposure and rigidity pattern.'),('Simple SSRI withdrawal','The syndrome follows serotonergic addition and has characteristic neuromuscular toxicity.')],
 'Clonus and exposure timing are high-value clues','**Excess serotonergic activity can produce autonomic, mental-status and neuromuscular abnormalities.**',['Rapid onset after a drug interaction is characteristic.','Severe rigidity may obscure some examination findings.'],'**Stop causative agents and provide sedation, cooling and organ support as needed.**',['Benzodiazepines help control agitation and muscle activity.','Selected antagonistic therapy is adjunctive rather than a substitute for resuscitation.'],[['Exposure','Serotonergic increase/interaction'],['Motor','Clonus/hyperreflexia'],['GI/autonomic','Diarrhea and sweating']],[ref('Management of serotonin syndrome/toxicity','https://doi.org/10.1111/bcp.16152')],style='clinical_scenario')

q('Which finding is more characteristic of serotonin toxicity than classic NMS?', 'Prominent clonus and hyperreflexia after a serotonergic change',[
 ('Generalized lead-pipe rigidity after dopamine blockade','This is more typical of classic NMS.'),('A slower evolving syndrome over days after antipsychotic escalation','That more strongly suggests NMS in the right context.'),('High CK alone','CK can rise in both and is not a reliable sole discriminator.')],
 'Use a pattern rather than one laboratory value','**The drug history and neuromuscular examination are particularly useful.**',['Hyperthermia and autonomic instability overlap.','Atypical presentations and mixed exposures can blur the distinction.'],'**Treat immediate physiological danger while clarifying the mechanism.**',['Withdraw suspected causative drugs.','Do not wait for perfect classification before airway, cooling and circulatory support.'],[['Serotonin toxicity','Clonus/hyperreflexia'],['Classic NMS','Rigidity/dopamine-blocker context'],['Shared','Fever and instability']],[CT])

q('A catatonic patient develops fever, severe autonomic instability and worsening rigidity before receiving any dopamine blocker. Which emergency should be considered?', 'Malignant catatonia',[
 ('NMS as established solely by fever despite no relevant exposure','The exposure history and preceding catatonia are important distinctions.'),('Benign voluntary mutism','The systemic deterioration is a medical emergency.'),('Uncomplicated negative symptoms','These do not explain fever and autonomic collapse.')],
 'Catatonia can become physiologically dangerous','**Malignant catatonia requires urgent multidisciplinary treatment.**',['NMS and malignant catatonia can overlap clinically.','Assess underlying psychiatric, neurological and medical causes.'],'**Provide intensive support and rapid specific treatment planning, often including ECT.**',['Do not simply escalate dopamine blockade.','Treat dehydration, thrombosis risk, renal injury and other complications.'],[['Preceding syndrome','Catatonia'],['Malignant features','Fever/autonomic instability'],['Urgency','Intensive support and ECT pathway']],[CT],style='clinical_scenario')

q('Ten days after childbirth, a woman develops near-total sleep loss, rapidly changing mood, confusion and delusional beliefs about the infant. Which action is appropriate?', 'Immediate emergency psychiatric and medical assessment with protection of mother and infant',[
 ('Manage as ordinary postpartum blues with routine review in several weeks','Psychosis and confusion are red flags beyond common transient blues.'),('Reassure that all postpartum insomnia is harmless','The whole syndrome indicates severe illness.'),('Assess only breastfeeding technique before any mental-health review','Practical support does not replace urgent safety and medical assessment.')],
 'Postpartum psychosis is an emergency','**Rapid-onset psychosis after childbirth can carry serious risk and often has an affective/bipolar relationship.**',['Assess medical causes, sleep loss and the longitudinal psychiatric history.','Support the infant while assessing the mother respectfully.'],'**Arrange specialist perinatal care urgently.**',['Treatment and feeding plans must account for maternal recovery and infant exposure.','Do not leave safety to reassurance alone.'],[['Timing','Often early postpartum'],['Red flags','Psychosis/confusion/severe sleep loss'],['Action','Urgent assessment and protection']],[ref('NICE antenatal/postnatal mental-health guideline','https://www.nice.org.uk/guidance/cg192/chapter/Recommendations')],style='clinical_scenario')

q('An agitated patient is able to engage and there is no immediate attack underway. Which initial approach is preferred?', 'Calm verbal de-escalation, adequate personal space and assessment of unmet needs and medical causes',[
 ('Immediate physical restraint for every raised voice','Restrictive interventions require a proportionate indication.'),('Confront the patient with several staff speaking at once','This can increase threat and confusion.'),('Administer a sedative without considering intoxication, hypoxia or hypoglycemia','Medical causes and respiratory risk need assessment.')],
 'Reduce perceived threat while establishing the cause','**De-escalation is an active clinical intervention.**',['Use one clear communicator, nonthreatening posture and choices when possible.','Agitation can reflect pain, delirium, intoxication or psychiatric illness.'],'**Escalate only as required by safety and response.**',['Use the least restrictive effective approach.','Document reassessment and the rationale for any medication or restraint.'],[['Initial approach','Calm communication/space'],['Assessment','Medical and psychiatric causes'],['Escalation','Proportionate and monitored']],[AG],style='clinical_scenario')

q('After parenteral rapid tranquillisation, which monitoring is necessary?', 'Respiratory rate, consciousness, pulse, blood pressure, temperature and other relevant physiological observations',[
 ('Only whether the patient has stopped shouting','Behavioral quietness can conceal oversedation or hypoxia.'),('No monitoring once the injection has been given','Drug and interaction effects can evolve.'),('Only a psychiatric symptom scale','It does not assess cardiorespiratory safety.')],
 'Sedation creates a new physiological monitoring obligation','**Respiratory depression, hypotension and other adverse effects can follow rapid tranquillisation.**',['Alcohol, opioids, comorbidity and repeated doses can increase risk.','Use the protocol’s observation frequency and higher-intensity monitoring when indicated.'],'**Ensure staff and equipment can respond to deterioration.**',['Avoid dose stacking before assessing the prior effect.','Reassess the cause and ongoing need for restriction or medication.'],[['Behavior','Not a safety monitor alone'],['Physiology','Breathing/circulation/consciousness'],['Process','Repeated documented observations']],[AG])

q('A patient presents after self-harm. Which statement about a numerical suicide-risk scale is correct?', 'It should not be used alone to predict suicide or decide discharge; a needs-based psychosocial assessment and formulation are required',[
 ('A low score guarantees safety and permits discharge without assessment','Scales cannot provide that individual prediction.'),('A high score automatically determines the only appropriate legal disposition','Clinical needs, capacity, context and local law require assessment.'),('A score replaces discussion of current intent, support and access to means','These are important assessment domains.')],
 'Assessment should guide care rather than create false certainty','**Risk scales have limited individual predictive ability.**',['Explore the episode, current state, protective factors and modifiable needs.','Use collaborative safety planning and appropriate follow-up.'],'**Base disposition on a comprehensive clinical assessment.**',['Address immediate medical and safeguarding concerns.','Do not use labels such as low risk as a substitute for a care plan.'],[['Scale','Not a prediction/discharge rule'],['Assessment','Needs and formulation'],['Plan','Safety and follow-up']],[SH],style='clinical_scenario')

q('After intentional self-poisoning, which care principle is appropriate?', 'Coordinate necessary medical treatment with timely psychosocial assessment rather than making one disappear behind the other',[
 ('Treat the poisoning and discharge automatically once blood tests improve','Psychosocial needs and recurrence prevention still require assessment.'),('Delay emergency medical stabilization until a full psychiatric interview is complete','Immediate physiological danger takes priority.'),('Refuse assessment because the patient has presented before','Repeated presentations may indicate ongoing unmet needs.')],
 'Physical and mental-health needs are both part of the emergency','**Intentional self-poisoning requires compassionate integrated care.**',['Stabilization and assessment can often proceed in parallel as the patient can participate.','Intoxication and capacity require careful reassessment.'],'**Agree a safe disposition and continuing support plan.**',['Review access to medicines and other modifiable risks collaboratively.','Communicate clearly between emergency, medical and mental-health teams.'],[['Medical','Treat current toxicity'],['Psychosocial','Understand needs/context'],['Continuity','Safe plan and follow-up']],[SH],style='clinical_scenario')

q('Which principle best describes assessment of decision-making capacity in a medically ill psychiatric patient?', 'Assess the specific decision at the relevant time with appropriate support; diagnosis alone does not determine capacity',[
 ('Any psychiatric diagnosis proves incapacity for all decisions','Capacity is not determined by diagnosis alone.'),('An unwise decision automatically proves incapacity','The reasoning abilities and understanding need assessment.'),('A previous capacity assessment is permanently valid despite new delirium','Capacity can fluctuate with illness and context.')],
 'Support the decision before judging the ability','**Understanding, retaining, using/weighing information and communicating a choice are relevant functional abilities in common clinical frameworks.**',['Legal tests and authority vary by jurisdiction.','Communication barriers and reversible confusion should be addressed.'],'**Document the decision-specific assessment and follow applicable local law.**',['Separate capacity from disagreement with the clinician.','Reassess when the patient’s state changes.'],[['Scope','Specific decision'],['Timing','Current state'],['Diagnosis','Does not decide capacity alone']],[ref('NICE decision-making and mental capacity guideline','https://www.nice.org.uk/guidance/ng108/chapter/Recommendations')])

q('A patient with restrictive eating has rapid weight loss, bradycardia, orthostatic hypotension, hypokalemia and a prolonged QT. BMI is not extremely low. Which conclusion is appropriate?', 'There may be serious medical instability requiring urgent assessment regardless of BMI alone',[
 ('A non-extreme BMI excludes an eating-disorder emergency','Rapid loss, vital signs, ECG and biochemical findings can indicate severe risk.'),('The ECG can be ignored if the patient denies symptoms','Dangerous electrolyte and rhythm abnormalities may be minimally symptomatic.'),('Only psychological treatment is needed before correcting potassium','Immediate physiological threats require medical treatment.')],
 'Body size alone is an unsafe severity measure','**Eating-disorder emergencies require integrated physical and psychiatric assessment.**',['Rate of loss, intake, purging, vitals, glucose/electrolytes and ECG all matter.','Refeeding requires a risk-aware nutrition plan.'],'**Coordinate medical stabilization with specialist eating-disorder care.**',['Monitor phosphate, potassium, magnesium and cardiac status as indicated.','Assess capacity, distress and support needs compassionately.'],[['Risk','Multidomain'],['BMI','Not sufficient alone'],['Care','Medical plus psychiatric']],[ref('RCPsych medical emergencies in eating disorders: MEED','https://www.rcpsych.ac.uk/improving-care/campaigning-for-better-mental-health-policy/college-reports/2022-college-reports/cr233')],style='clinical_scenario')

q('Why does switching from fluoxetine to an irreversible MAOI generally require a longer washout than switching from many shorter-acting SSRIs?', 'Fluoxetine and its active metabolite can persist for weeks and create a dangerous serotonergic interaction',[
 ('Fluoxetine has no active metabolite and disappears within hours','Norfluoxetine is active and prolonged persistence matters.'),('MAOIs neutralize residual SSRIs immediately','Combining residual serotonergic effects can cause severe toxicity.'),('All antidepressants can be cross-tapered into an irreversible MAOI without restriction','Drug-specific washout and specialist guidance are essential.')],
 'A stopped drug may remain pharmacologically active','**Long half-lives extend the interaction window.**',['Use the current product-specific switching guidance and clinical context.','Higher exposure or impaired clearance can change the required plan.'],'**Use a supervised switching strategy.**',['The commonly specified fluoxetine-to-MAOI interval is at least five weeks, with individual review.','Do not apply that interval blindly to every other drug pair.'],[['Fluoxetine','Long persistence'],['Norfluoxetine','Active metabolite'],['MAOI switch','Extended drug-specific washout']],[ref('NHS SPS SSRI switching guidance','https://sps.nhs.uk/articles/ssris-to-other-antidepressants-switching-in-adults/')])

if __name__=='__main__':finalize('Psychiatry',6,'Psychopharmacology and Psychiatric Emergencies','psych-emergencies',rows,24)
